const tabs=[...document.querySelectorAll('[role="tab"]')];function selectTab(tab){tabs.forEach(item=>{const active=item===tab;item.setAttribute('aria-selected',String(active));item.tabIndex=active?0:-1;document.getElementById(item.getAttribute('aria-controls')).hidden=!active})}tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index-1+tabs.length)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();selectTab(tabs[next]);tabs[next].focus()})});const header=document.querySelector('.site-header');let lastY=0;addEventListener('scroll',()=>{const y=scrollY;header.style.transform=y>lastY&&y>140?'translateY(-100%)':'translateY(0)';lastY=y},{passive:true});
